include('../config.php'); require_once __DIR__.'/../base/FleetPolicy.class.php'; require_once __DIR__.'/../base/ResearchBlueprintPolicy.class.php'; require_once __DIR__.'/../base/CraftingPolicy.class.php';
$pagegen=new page_gen();$pagegen->round_to=4;$pagegen->start();$s=new Game();if(!$s->loggedIn||!isset($_GET['time'])){header('Location: ../index.php');exit;}$db=$s->db_link;$uid=(int)$_SESSION['userid'];ResearchBlueprintPolicy::ensureTable($db);if(empty($_SESSION['fleet_csrf']))$_SESSION['fleet_csrf']=bin2hex(random_bytes(16));$csrf=$_SESSION['fleet_csrf'];$notice='';$error='';$db->query("INSERT IGNORE INTO player_resource_wallet(uid) VALUES ($uid)");
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))$error='Security validation failed.';else{$action=(string)($_POST['fleet_action']??'');if($action==='build'){$planet=(int)($_POST['planet_id']??0);$type=(string)($_POST['ship_type']??'');$qty=max(1,min(100000,(int)($_POST['quantity']??0)));$b=FleetPolicy::blueprint($type);$cost=FleetPolicy::cost($type,$qty);$planetQ=$db->query("SELECT pid FROM planets WHERE pid=$planet AND uid=$uid LIMIT 1");$q=$db->query("SELECT COUNT(*) c FROM shipyard_queue WHERE uid=$uid AND status='building'");$queue=(int)($q?$q->fetch_assoc()['c']:0);$w=$db->query("SELECT metal,crystal,energy FROM player_resource_wallet WHERE uid=$uid LIMIT 1");$wallet=$w?$w->fetch_assoc():[];if(!$b||$planet<=0||!$planetQ||$planetQ->num_rows!==1)$error='Select a valid ship blueprint and planet.';elseif(!ResearchBlueprintPolicy::unlocked($db,$uid,$type))$error='Research this blueprint before constructing it.';elseif($queue>=FleetPolicy::MAX_QUEUE)$error='Shipyard construction queue is full.';elseif((int)($wallet['metal']??0)<$cost['metal']||(int)($wallet['crystal']??0)<$cost['crystal']||(int)($wallet['energy']??0)<$cost['energy'])$error='Insufficient shipyard resources.';else{$eta=date('Y-m-d H:i:s',time()+($cost['build_minutes']*60));$db->begin_transaction();$ok=$db->query("UPDATE player_resource_wallet SET metal=metal-{$cost['metal']},crystal=crystal-{$cost['crystal']},energy=energy-{$cost['energy']} WHERE uid=$uid AND metal>={$cost['metal']} AND crystal>={$cost['crystal']} AND energy>={$cost['energy']} LIMIT 1");$st=$db->prepare('INSERT INTO shipyard_queue(uid,planet_id,ship_type,quantity,metal_cost,crystal_cost,energy_cost,completes_at) VALUES (?,?,?,?,?,?,?,?)');$st->bind_param('iisiiiis',$uid,$planet,$type,$qty,$cost['metal'],$cost['crystal'],$cost['energy'],$eta);if(!$ok||$db->affected_rows!==1||!$st->execute()){$db->rollback();$error='Construction could not be queued.';}else{$db->commit();$notice='Construction qu