RuntimeException('Fleet inventory reservation failed.');}$eta=date('Y-m-d H:i:s',time()+max(10,min(1440,abs($dest-$origin)*2)));$fittingJson=json_encode(ModuleFittingPolicy::normalize($fitting),JSON_THROW_ON_ERROR);$st=$db->prepare('INSERT INTO fleet_deployments(uid,origin_planet_id,destination_planet_id,fleet_json,fitting_json,attack_power,defense_power,arrive_at) VALUES (?,?,?,?,?,?,?,?)');$st->bind_param('iiissiis',$uid,$origin,$dest,$fleetJson,$fittingJson,$power['attack'],$power['defense'],$eta);if(!$st->execute())throw new RuntimeException('Fleet deployment failed.');$db->commit();$notice='Fleet deployment launched; inventory reserved until arrival at '.$eta.'.';}catch(Throwable $e){$db->rollback();$error=$e->getMessage()?:'Fleet deployment failed.';}}}}}}}
$queue=$db->query("SELECT queue_id,planet_id,ship_type,quantity,completes_at,status FROM shipyard_queue WHERE uid=$uid ORDER BY queue_id DESC LIMIT 25");$inventory=$db->query("SELECT planet_id,ship_type,quantity FROM player_fleet_inventory WHERE uid=$uid AND quantity>0 ORDER BY planet_id,ship_type");$deployments=$db->query("SELECT deployment_id,origin_planet_id,destination_planet_id,attack_power,defense_power,status,arrive_at FROM fleet_deployments WHERE uid=$uid ORDER BY deployment_id DESC LIMIT 25");$wallet=$db->query("SELECT metal,crystal,energy FROM player_resource_wallet WHERE uid=$uid LIMIT 1")->fetch_assoc();echo '<div class="comm-shell"><div class="page-hub-head"><span class="rts-kicker">UNIVERSE CIVILIZATION // FLEET COMMAND</span><h3>Shipyard and Fleet Operations</h3><p>Construct ships, assemble fleets, and deploy them across interplanetary theaters.</p></div>';if($notice)echo '<div class="comm-alert">'.htmlspecialchars($notice,ENT_QUOTES,'UTF-8').'</div>';if($error)echo '<div class="comm-alert comm-error">'.htmlspecialchars($error,ENT_QUOTES,'UTF-8').'</div>';echo '<section class="comm-card"><h4>Resource Wallet</h4><p>Metal '.number_format((int)$wallet['metal']).' · Crystal '.number_format((int)$wallet['crystal']).' · Energy '.number_format((int)$wallet['energy']).'</p><form method="post" action="/modules/fleet.php?time='.time().'" class="inline-form"><input type="hidden" name="csrf" value="'.htmlspecialchars($csrf,ENT_QUOTES,'UTF-8').'"/><input type="hidden" name="fleet_action" value="build"/><input name="planet_id" type="number" min="1" placeholder="Planet ID" required><select name="ship_type">';foreach(FleetPolicy::BLUEPRINTS as $key=>$b)echo '<option value="'.$key.'">'.htmlspecialchars($b['name'],ENT_QUOTES,'UTF-8').' (A'.$b['attack'].' / D'.$b['defense'].')</option>';echo '</select><input name="quantity" type="number" min="1" max="100000" value="1" required><button class="comm-btn">Queue Construction</button></form></section><section class="comm-card