td><td>'.number_format((int)$r['attack_power']).'</td><td>'.number_format((int)$r['defense_power']).'</td><td>'.htmlspecialchars($r['status'],ENT_QUOTES,'UTF-8').'</td><td>'.htmlspecialchars($r['arrive_at'],ENT_QUOTES,'UTF-8').'</td></tr>';echo '</table></div></section></div>'; $pagegen->stop();print('page generation time: '.$pagegen->gen()); ?>
